from pathlib import Path
p=Path('/home/ubuntu/labrkp-workforce/server/marketplaceApi.ts')
s=p.read_text()
s=s.replace('const memoryPublishedWorkers: any[] = [];', 'const memoryPublishedWorkers: any[] = [];\nconst memoryReviews: any[] = [];')
anchor='export function publicWorkerFromApplication(application: any) {'
helper='export function aggregateRating(reviews: Array<{ rating: number }>) {\n  if (!reviews.length) return { rating: "New", reviews: 0 };\n  const average = reviews.reduce((sum, review) => sum + Number(review.rating), 0) / reviews.length;\n  return { rating: average.toFixed(1), reviews: reviews.length };\n}\n\n'
s=s.replace(anchor,helper+anchor,1)
needle='  app.get("/api/workers/:id/profile", async (req, res) => { const database = await getDb(); const profile = database ? await database.collection("workerProfiles").findOne({ workerId: req.params.id }) : null; return profile ? res.json(profile) : res.status(404).json({ error: "Worker profile not found" }); });\n'
insert='  app.get("/api/workers/:id/reviews", async (req, res) => { const database = await getDb(); const reviews = database ? await database.collection("workerReviews").find({ workerId: req.params.id }).sort({ createdAt: -1 }).toArray() : memoryReviews.filter((review) => review.workerId === req.params.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt)); return res.json({ reviews, summary: aggregateRating(reviews) }); });\n  app.post("/api/workers/:id/reviews", async (req, res) => { const rating = Number(req.body.rating); const name = String(req.body.customerName || "").trim(); const comment = String(req.body.comment || "").trim(); if (!Number.isInteger(rating) || rating < 1 || rating > 5 || !name || !comment) return res.status(400).json({ error: "Customer name, rating from 1 to 5, and review are required" }); const review = { reviewId: createReference(), workerId: req.params.id, customerName: name, rating, comment, createdAt: now() }; const database = await getDb(); if (database) { await database.collection("workerReviews").insertOne(review); const allReviews = await database.collection("workerReviews").find({ workerId: req.params.id }).toArray(); const summary = aggregateRating(allReviews); await database.collection("publishedWorkers").updateOne({ $or: [{ applicationId: req.params.id }, { id: req.params.id }] }, { $set: summary }); return res.status(201).json({ review, summary }); } memoryReviews.unshift(review); const ownReviews = memoryReviews.filter((item) => item.workerId === req.params.id); const summary = aggregateRating(ownReviews); const published = memoryPublishedWorkers.find((item) => String(item.id) === req.params.id || item.applicationId === req.params.id); if (published) Object.assign(published, summary); return res.status(201).json({ review, summary }); });\n'+needle
if needle not in s: raise SystemExit('profile anchor missing')
